from __future__ import annotations
from typing import Any, Callable, Optional
import reactive.signal as sig

class Effect:
    def __init__(self, fn: Callable[[], None]):
        self._fn = fn
        self._dependencies: set[Any] = set()
        self._run()

    def _run(self) -> None:
        # BUG: Does not clean up previous dependencies, leaking subscriptions
        prev = sig._CURRENT_SUBSCRIBER
        sig._CURRENT_SUBSCRIBER = self
        try:
            self._fn()
        finally:
            sig._CURRENT_SUBSCRIBER = prev

    def _notify(self) -> None:
        if sig._BATCH_DEPTH > 0:
            sig._PENDING_EFFECTS.add(self)
        else:
            self._run()

def create_effect(fn: Callable[[], None]) -> Effect:
    return Effect(fn)

