from __future__ import annotations
from typing import Any, Callable, Generic, Optional, TypeVar, Set

T = TypeVar('T')
_CURRENT_SUBSCRIBER: Optional[Any] = None
_BATCH_DEPTH: int = 0
_PENDING_EFFECTS: Set[Any] = set()

class Signal(Generic[T]):
    def __init__(self, value: T):
        self._value = value
        self._subscribers: set[Any] = set()

    def get(self) -> T:
        global _CURRENT_SUBSCRIBER
        if _CURRENT_SUBSCRIBER is not None:
            self._subscribers.add(_CURRENT_SUBSCRIBER)
            _CURRENT_SUBSCRIBER._dependencies.add(self)
        return self._value

    def set(self, new_value: T) -> None:
        if self._value == new_value:
            return
        self._value = new_value
        # BUG: Fails to honor batch mode and incorrectly iterates mutating set
        for sub in list(self._subscribers):
            sub._notify()

class Computed(Generic[T]):
    def __init__(self, fn: Callable[[], T]):
        self._fn = fn
        self._value: Optional[T] = None
        self._dirty = True
        self._dependencies: set[Any] = set()
        self._subscribers: set[Any] = set()

    def _notify(self) -> None:
        self._dirty = True
        for sub in list(self._subscribers):
            sub._notify()

    def get(self) -> T:
        global _CURRENT_SUBSCRIBER
        if _CURRENT_SUBSCRIBER is not None:
            self._subscribers.add(_CURRENT_SUBSCRIBER)
            _CURRENT_SUBSCRIBER._dependencies.add(self)
        if self._dirty:
            prev = _CURRENT_SUBSCRIBER
            _CURRENT_SUBSCRIBER = self
            try:
                self._value = self._fn()
                self._dirty = False
            finally:
                _CURRENT_SUBSCRIBER = prev
        return self._value  # type: ignore

def create_signal(val: T) -> tuple[Callable[[], T], Callable[[T], None]]:
    s = Signal(val)
    return (s.get, s.set)

def create_computed(fn: Callable[[], T]) -> Callable[[], T]:
    c = Computed(fn)
    return c.get
